def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    row_cuts = [-1] + sep_rows + [h]
    col_cuts = [-1] + sep_cols + [w]
    regions = [
        (row_cuts[i] + 1, row_cuts[i + 1],
         col_cuts[j] + 1, col_cuts[j + 1])
        for i in range(len(row_cuts) - 1)
        for j in range(len(col_cuts) - 1)
    ]

    separator_cells = set(sep_rows), set(sep_cols)
    counts = {}
    for r0, r1, c0, c1 in regions:
        for r in range(r0, r1):
            for c in range(c0, c1):
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    background = max(counts, key=counts.get)

    source = max(
        regions,
        key=lambda box: sum(
            grid[r][c] != background
            for r in range(box[0], box[1])
            for c in range(box[2], box[3])
        )
    )
    sr0, sr1, sc0, sc1 = source
    out = [row[:] for row in grid]

    for r0, r1, c0, c1 in regions:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = grid[sr0 + (r - r0)][sc0 + (c - c0)]

    return out
